const BookOpenUI=(()=>{
 const E=id=>document.getElementById(id);let candidate=null,listStart=0,controller=null,working=false;
 function showMenu(){const r=E('openBook').getBoundingClientRect(),m=E('bookOpenMenu'),width=Math.min(320,Math.max(220,r.width));m.style.width=width+'px';m.style.left=Math.max(8,Math.min(r.left,innerWidth-width-8))+'px';m.style.right='auto';m.style.top=Math.max(8,Math.min(r.bottom+5,innerHeight-160))+'px';m.hidden=false;E('openBook').setAttribute('aria-expanded','true')}
 function closeMenu(){E('bookOpenMenu').hidden=true;E('openBook').setAttribute('aria-expanded','false')}
 function allowed(){if(busy||working||BetaTranslation.isActive()){SettingsUI.toast('현재 작업을 완료하거나 취소한 뒤 책을 열어 주세요.');return false}return true}
 function disposeCandidate(){if(candidate){candidate.dispose();candidate=null}}
 function progress(text){E('bookProgressText').textContent=text}
 function begin(){working=true;busy=true;controller=new AbortController();E('bookOpenCancel').disabled=false;progress('이미지 목록을 확인하고 있습니다…');E('bookOpenProgress').showModal();return controller.signal}
 function finish(){working=false;busy=false;controller=null;E('bookOpenProgress').close()}
 function report(e){const message=e.name==='AbortError'?'책 열기를 취소했습니다. 기존 책은 유지됩니다.':'책을 열지 못했습니다: '+e.message;status(message);SettingsUI.toast(message)}
 function preview(){listStart=0;E('imageBookSummary').textContent=candidate.title+' · '+candidate.entries.length+'장 · '+(candidate.bytes<104858?(candidate.bytes/1024).toFixed(1)+'KB':(candidate.bytes/1048576).toFixed(1)+'MB')+(candidate.ignored?' · 이미지가 아닌 파일/숨김 파일 '+candidate.ignored+'개 제외':'');drawList();E('imageBookPreview').showModal()}
 function drawList(){const list=E('imageBookList');list.textContent='';list.start=listStart+1;for(const entry of candidate.entries.slice(listStart,listStart+50)){const li=document.createElement('li');li.textContent=entry.path;list.append(li)}E('imageListRange').textContent=(listStart+1)+'–'+Math.min(listStart+50,candidate.entries.length)+' / '+candidate.entries.length;E('imageListPrev').disabled=listStart===0;E('imageListNext').disabled=listStart+50>=candidate.entries.length;list.scrollTop=0}
 async function activate(){if(!candidate||!allowed())return;E('imageBookPreview').close();const next=candidate,signal=begin();let committed=false;try{await openImageBook(next,{signal,onProgress:progress,onCommit:()=>{committed=true;E('bookOpenCancel').disabled=true;progress('책을 표시하고 있습니다…')}});candidate=null;finish();await render()}catch(e){if(!committed)disposeCandidate();else candidate=null;finish();report(e)}}
 async function prepare(factory,single=false){if(!allowed())return;disposeCandidate();const signal=begin();try{candidate=await factory(signal);if(signal.aborted)throw new DOMException('취소됨','AbortError');finish();if(single)await activate();else preview()}catch(e){disposeCandidate();finish();report(e)}}
 async function file(file){if(!file)return;if(/\.zip$/i.test(file.name)||file.type==='application/zip')await prepare(signal=>ImageBook.zip(file,{signal,onProgress:progress}));else if(/\.(png|jpe?g|webp)$/i.test(file.name))await prepare(()=>ImageBook.files([file],file.name,'image'),true);else if(allowed()){BetaTranslation.cancelSelection();await openBookFile(file)}}
 function init(){document.body.append(E('bookOpenMenu'));const folderSupported='webkitdirectory'in E('folder');E('openBookFolder').disabled=!folderSupported;if(!folderSupported)E('folderSupport').textContent='이 환경에서는 ZIP으로 열어 주세요.';
  E('openBook').onclick=()=>{const show=E('bookOpenMenu').hidden;closeMenu();if(show)showMenu()};E('openBookFile').onclick=()=>{closeMenu();if(allowed())E('file').click()};E('openBookFolder').onclick=()=>{closeMenu();if(allowed())E('folder').click()};E('file').onchange=async e=>{const chosen=e.target.files[0];e.target.value='';await file(chosen)};E('folder').onchange=async e=>{const chosen=Array.from(e.target.files);e.target.value='';if(chosen.length)await prepare(()=>ImageBook.files(chosen))};
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!E('bookOpenMenu').hidden){e.preventDefault();closeMenu();E('openBook').focus()}});document.addEventListener('click',e=>{if(!e.target.closest('.book-open,.book-open-menu'))closeMenu()});E('openBook').onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();showMenu();E('openBookFile').focus()}};window.addEventListener('resize',closeMenu);document.querySelector('aside').addEventListener('scroll',closeMenu);E('bookOpenMenu').onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeMenu();E('openBook').focus()}else if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const buttons=[E('openBookFile'),E('openBookFolder')].filter(b=>!b.disabled),i=buttons.indexOf(document.activeElement);buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+1)%buttons.length].focus()}};
  E('imageBookCancel').onclick=()=>{E('imageBookPreview').close();disposeCandidate()};E('imageBookPreview').addEventListener('cancel',()=>disposeCandidate());E('imageBookConfirm').onclick=activate;E('imageListPrev').onclick=()=>{listStart=Math.max(0,listStart-50);drawList()};E('imageListNext').onclick=()=>{listStart+=50;drawList()};E('bookOpenCancel').onclick=()=>{if(!E('bookOpenCancel').disabled){controller?.abort();progress('취소하고 있습니다…');E('bookOpenCancel').disabled=true}};E('bookOpenProgress').addEventListener('cancel',e=>{e.preventDefault();if(!E('bookOpenCancel').disabled)E('bookOpenCancel').click()});
 }
 return {init};
})();
BookOpenUI.init();
